def prod_signs(arr):
    if not arr:
        return None
    sign_product = 1
    sum_magnitudes = 0
    for x in arr:
        if x > 0:
            sign_product *= 1
        elif x < 0:
            sign_product *= -1
        else:
            sign_product = 0
        sum_magnitudes += abs(x)
    return sum_magnitudes * sign_product
